    "/api/v1/appointments/{id}/messages": {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        /**
         * The Messages tab: every text filed under this appointment, oldest first
         * @description Outbound texts the app sent for the appointment and inbound replies attributed to it (a job in progress, else the nearest upcoming booking within 72 hours, else the last completed one within 14 days). `customer.canMessage` is false when a send would be refused. No phone number is returned. `markRead=true` clears the customer's unread replies.
         */
        get: {
            parameters: {
                query?: {
                    limit?: number;
                    markRead?: boolean;
                };
                header?: never;
                path: {
                    id: string;
                };
                cookie?: never;
            };
            requestBody?: never;
            responses: {
                /** @description Default Response */
                200: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        "application/json": {
                            /** @description A staff reply paused the AI on this thread until then (null when not paused or the pause is over) */
                            aiPausedUntil: string | null;
                            /** @description The AI assistant answers texts now (AI_ENABLED and Settings → Assistant on): show the "AI paused" line only then */
                            assistantActive: boolean;
                            customer: {
                                canMessage: boolean;
                                hasPhone: boolean;
                                id: string;
                                name: string;
                                optedOut: boolean;
                                smsOptedIn: boolean;
                            } | null;
                            /** @description The AI handoff of the client’s number (ADR 0160): closed by a staff reply */
                            handoff: {
                                /** @description An open handoff: the client asked for a person (AGENT) or the assistant could not help; staff answer */
                                open: boolean;
                                /** @description Why it was handed off (null when none is open) */
                                reason: string | null;
                                /** @description When the open handoff began (null when none is open) */
                                since: string | null;
                            };
                            items: {
                                appointmentId: string | null;
                                at: string;
                                attachments: {
                                    contentType: string;
                                    index: number;
                                    name: string | null;
                                    size: number | null;
                                    /** @enum {string} */
                                    status: "stored" | "listed" | "unavailable" | "skipped";
                                }[];
                                /** @enum {string} */
                                author: "staff" | "system" | "customer" | "ai";
                                /** @enum {string} */
                                channel: "sms" | "email" | "internal";
                                customerId: string | null;
                                /** @enum {string} */
                                direction: "in" | "out";
                                error: string | null;
                                /** @enum {string} */
                                from: "staff" | "system" | "customer";
                                id: string;
                                /** @enum {string} */
                                kind: "sms" | "mms";
                                read: boolean;
                                segments: number;
                                senderName: string | null;
                                /** @enum {string} */
                                status: "queued" | "sending" | "sent" | "delivered" | "failed" | "received" | "canceled" | "expired";
                                templateKey: string | null;
                                text: string;
                                time: string;
                            }[];
                            unread: number;
                        };
                    };
                };
            };
        };
        put?: never;
        /**
         * Send a text to the appointment's customer
         * @description Free `text` goes out as an SMS (class staff_message) and a `templateKey` of a quick reply or an automation renders its wording; variables not supplied (`first`, `time`, `when`, `bay`) are filled from the appointment. The text passes the SMS policy: 422 SMS_OPTED_OUT after a STOP, SMS_NOT_OPTED_IN without consent, SMS_NO_PHONE without a number, SMS_TOO_LONG above the segment cap. It is queued, not sent inline; `message.status` events follow on the messages channel.
         */
        post: {
            parameters: {
                query?: never;
                header?: never;
                path: {
                    id: string;
                };
                cookie?: never;
            };
            requestBody: {
                content: {
                    "application/json": {
                        templateKey?: string;
                        text?: string;
                        vars?: {
                            [key: string]: string | number;
                        };
                    };
                };
            };
            responses: {
                /** @description Default Response */
                201: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        "application/json": {
                            held: boolean;
                            holdUntil: string | null;
                            message: {
                                appointmentId: string | null;
                                at: string;
                                attachments: {
                                    contentType: string;
                                    index: number;
                                    name: string | null;
                                    size: number | null;
                                    /** @enum {string} */
                                    status: "stored" | "listed" | "unavailable" | "skipped";
                                }[];
                                /** @enum {string} */
                                author: "staff" | "system" | "customer" | "ai";
                                /** @enum {string} */
                                channel: "sms" | "email" | "internal";
                                customerId: string | null;
                                /** @enum {string} */
                                direction: "in" | "out";
                                error: string | null;
                                /** @enum {string} */
                                from: "staff" | "system" | "customer";
                                id: string;
                                /** @enum {string} */
                                kind: "sms" | "mms";
                                read: boolean;
                                segments: number;
                                senderName: string | null;
                                /** @enum {string} */
                                status: "queued" | "sending" | "sent" | "delivered" | "failed" | "received" | "canceled" | "expired";
                                templateKey: string | null;
                                text: string;
                                time: string;
                            };
                            /** @enum {boolean} */
                            queued: true;
                            segments: number;
                        };
                    };
                };
            };
        };
        delete?: never;
        options?: never;
        head?: never;
        patch?: never;
        trace?: never;
    };
